function dateLabel(value){if(!value)return'Unknown date';const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString():'Approximate date';}
function customerName(id){const row=records('customers').find(x=>text(value(x,'Customer ID','customerId'))===text(id));return text(value(row,'Customer Name','name'))||'No customer';}
