function meetingSources(row){const sources=Array.isArray(row?.sourceTypes)?row.sourceTypes.map(x=>text(x,80).toUpperCase()).filter(Boolean):[];if(sources.length)return Array.from(new Set(sources));const segments=Array.isArray(row?.segments)?row.segments:[];return Array.from(new Set(segments.map(sourceType).filter(Boolean)));}
