function projectLegacySiteVisits(){return records('siteCaptureSessions').map((row,index)=>{const sid=text(value(row,'Capture Session ID','captureSessionId','Session ID','sessionId'),180);if(!sid)return null;const transcript=text(value(row,'Walkthrough Transcript','walkthroughTranscript'),24000),requests=Array.isArray(row['Walkthrough Customer Requests'])?row['Walkthrough Customer Requests']:[],conditions=Array.isArray(row['Walkthrough Site Conditions'])?row['Walkthrough Site Conditions']:[],unknowns=Array.isArray(row['Walkthrough Unknowns'])?row['Walkthrough Unknowns']:[],measurements=Array.isArray(row['Walkthrough Spoken Measurements'])?row['Walkthrough Spoken Measurements']:[];return{meetingId:`LEGACY-SITE-${sid}`,meetingType:'Site Visit',title:text(value(row,'Project Title','projectTitle'))||'Historical Site Visit',status:'Historical',occurredAt:text(value(row,'Created Time','createdAt','Updated Time','updatedAt')),updatedAt:text(value(row,'Updated Time','updatedAt')),customerId:text(value(row,'Customer ID','customerId')),quoteId:text(value(row,'Quote ID','quoteId')),siteCaptureSessionId:sid,legacyProjection:true,sourceTypes:transcript?['RECORDED_VIDEO_AUDIO']:['IMPORTED_NOTE'],segments:transcript?[{segmentId:`LEGACY-WALKTHROUGH-${sid}`,sourceType:'RECORDED_VIDEO_AUDIO',transcript}]:[],transcript,summary:text(value(row,'Professional Notes','professionalNotes')),customerRequests:requests.map((x,i)=>({text:text(x),sourceType:'RECORDED_VIDEO_AUDIO',sourceReferenceId:`LEGACY-${i}`,verificationStatus:'RECORDED_NOT_INDEPENDENTLY_VERIFIED'})),siteConditions:conditions.map((x,i)=>({text:text(x),sourceType:'RECORDED_VIDEO_AUDIO',sourceReferenceId:`LEGACY-C-${i}`,verificationStatus:'RECORDED_NOT_INDEPENDENTLY_VERIFIED'})),unknowns:unknowns.map((x,i)=>({text:text(x),sourceType:'RECORDED_VIDEO_AUDIO',sourceReferenceId:`LEGACY-U-${i}`,verificationStatus:'RECORDED_NOT_INDEPENDENTLY_VERIFIED'})),measurements};}).filter(Boolean);}
function allMeetings(){const actual=actualMeetings(),ids=new Set(actual.map(meetingId));return actual.concat(projectLegacySiteVisits().filter(row=>!ids.has(meetingId(row)))).sort((a,b)=>new Date(updated(b)||occurred(b)||0)-new Date(updated(a)||occurred(a)||0));}
function findMeeting(id){return allMeetings().find(row=>meetingId(row)===text(id))||null;}
function applyMeetingSnapshot(record){const s=snapshot();if(!s.meetings)s.meetings=[];const id=meetingId(record),index=s.meetings.findIndex(row=>meetingId(row)===id);if(index>=0)s.meetings[index]=record;else s.meetings.unshift(record);}
function cleanRecord(record){const next={...record};delete next.__localPending;return next;}

function client(){const shared=window.H38_SUPABASE_SHARED_CLIENT?.ensure?.();if(shared)return shared;const cfg=window.H38_BUSINESS_OFFICE_SUPABASE||{};if(!cfg.url||!cfg.publishableKey||!window.supabase)throw Error('Secure Business Office connection is unavailable.');return window.supabase.createClient(cfg.url,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}});}
async function authSession(force=false){const api=client();let result=await api.auth.getSession();if(result.error)throw result.error;let session=result.data?.session;if(!session?.user)throw Error('Sign in again before saving meeting evidence.');if(force||Number(session.expires_at||0)*1000<Date.now()+120000){const refreshed=await api.auth.refreshSession();if(refreshed.error||!refreshed.data?.session)throw refreshed.error||Error('Secure session refresh failed.');session=refreshed.data.session;}const verified=await api.auth.getUser(session.access_token);if(verified.error||!verified.data?.user)throw verified.error||Error('Secure session is invalid.');return{api,session,user:verified.data.user};}
async function proof(action,meeting,details={}){if(!navigator.onLine||!office().businessId)return false;try{const {api,user}=await authSession();const result=await api.from('business_proof_log').insert({business_id:office().businessId,actor_user_id:user.id,action_type:action,entity_type:'Meeting',entity_id:null,result:'PASS',details:{meetingId:meetingId(meeting),ownerReviewRequired:true,automaticApproval:false,automaticCustomerSending:false,automaticPurchase:false,automaticPayment:false,automaticScheduling:false,externalActionOccurred:false,build:BUILD,...details},external_action_occurred:false});if(result.error)throw result.error;return true;}catch(error){console.warn('[H38 meeting proof]',error?.message||error);return false;}}
async function persistMeeting(record,action='MEETING_UPDATED'){const id=meetingId(record);if(!id)throw Error('Meeting identity is incomplete.');record.updatedAt=now();record['Updated Time']=record.updatedAt;record['Meeting ID']=id;record.meetingId=id;record['Business ID']=office().businessId;record.businessId=office().businessId;const clean=cleanRecord(record);if(typeof window.queueOperation!=='function')throw Error('Business Office offline queue is unavailable.');await window.queueOperation(action,'Meeting',id,{__h38Record:{collection:COLLECTION,record:clean}},{collection:COLLECTION,record:clean,idKeys:['Meeting ID','meetingId']},false);applyMeetingSnapshot({...clean,__localPending:true});if(navigator.onLine&&office().bridgeReady&&typeof window.sync==='function'){try{await window.sync(false);}catch(error){console.warn('[H38 meeting sync]',error?.message||error);}}return clean;}
async function refreshMeeting(id){if(!navigator.onLine)return findMeeting(id);try{const {api}=await authSession();const result=await api.from('business_records').select('payload').eq('business_id',office().businessId).eq('collection',COLLECTION).eq('record_key',id).eq('record_status','active').maybeSingle();if(result.error)throw result.error;if(result.data?.payload){applyMeetingSnapshot(result.data.payload);return result.data.payload;}}catch(error){console.warn('[H38 meeting refresh]',error?.message||error);}return findMeeting(id);}
async function ensureServerMeeting(id){if(!navigator.onLine)throw Error('This meeting is safely saved on this device. Reconnect before AI organization.');if(office().bridgeReady&&typeof window.sync==='function')await window.sync(false);let row=await refreshMeeting(id);if(row&&!row.__localPending)return row;const local=findMeeting(id);if(!local)throw Error('Meeting record is unavailable.');const {api,user}=await authSession();const clean=cleanRecord(local);const result=await api.from('business_records').upsert({business_id:office().businessId,collection:COLLECTION,record_key:id,payload:clean,record_status:'active',created_by:user.id,updated_by:user.id},{onConflict:'business_id,collection,record_key'});if(result.error)throw result.error;return clean;}
async function callFunction(slug,body,timeout=180000,retry=false){const cfg=window.H38_BUSINESS_OFFICE_SUPABASE||{},auth=await authSession(retry),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(`${cfg.url}/functions/v1/${slug}`,{method:'POST',mode:'cors',cache:'no-store',credentials:'omit',headers:{authorization:`Bearer ${auth.session.access_token}`,apikey:cfg.publishableKey,'content-type':'application/json','x-client-info':BUILD},body:JSON.stringify(body),signal:controller.signal});const payload=await response.json().catch(()=>({}));if(response.status===401&&!retry)return callFunction(slug,body,timeout,true);if(!response.ok||payload?.status!=='PASS')throw Error(payload?.message||`${slug} failed (${response.status}).`);return payload;}finally{clearTimeout(timer);}}

function baseMeeting(fields={}){const id=fields.meetingId||uid('MEETING'),created=now(),type=text(fields.meetingType)||'Other Conversation';return{'Meeting ID':id,meetingId:id,'Business ID':office().businessId,businessId:office().businessId,'Meeting Type':type,meetingType:type,'Title':text(fields.title)||type,title:text(fields.title)||type,'Status':fields.status||'Open',status:fields.status||'Open','Occurred At':fields.occurredAt||created,occurredAt:fields.occurredAt||created,'Created Time':created,createdAt:created,'Updated Time':created,updatedAt:created,'Customer ID':text(fields.customerId),customerId:text(fields.customerId),'Vendor ID':text(fields.vendorId),vendorId:text(fields.vendorId),'Site Visit ID':text(fields.siteVisitId),siteVisitId:text(fields.siteVisitId),'Site Capture Session ID':text(fields.siteCaptureSessionId),siteCaptureSessionId:text(fields.siteCaptureSessionId),'Quote ID':text(fields.quoteId),quoteId:text(fields.quoteId),'Job ID':text(fields.jobId),jobId:text(fields.jobId),'Project ID':text(fields.projectId),projectId:text(fields.projectId),participantNames:Array.isArray(fields.participantNames)?fields.participantNames:[],sourceTypes:[],segments:[],manualNotes:[],transcript:'',summary:'',customerRequests:[],decisions:[],commitments:[],siteConditions:[],measurements:[],unknowns:[],questionsToAsk:[],actionItems:[],followUps:[],attachments:[],sourceReferences:[],nextMeetingContext:{},ownerReviewStatus:'REQUIRED',structuredStatus:'NOT_STARTED',approximateOccurredAt:fields.approximateOccurredAt===true,automaticApproval:false,automaticCustomerSending:false,automaticPurchase:false,automaticPayment:false,automaticScheduling:false};}
async function createMeeting(fields={},segment=null){const meeting=baseMeeting(fields);if(segment){meeting.segments.push(segment);meeting.sourceTypes=[sourceType(segment)];}await persistMeeting(meeting,'MEETING_CREATED');if(segment)await proof(segment.sourceType?.includes('RECOLLECTION')?'MEETING_RECOLLECTION_ADDED':'MEETING_CREATED',meeting,{sourceType:segment.sourceType});return meeting;}

function customerOptions(selected=''){return'<option value="">No customer / business-only meeting</option>'+records('customers').map(row=>{const id=text(value(row,'Customer ID','customerId')),name=text(value(row,'Customer Name','name'))||id;return`<option value="${html(id)}" ${id===selected?'selected':''}>${html(name)}</option>`;}).join('');}
